// Helper utilities for space-weather simulation
DONKI_SNAPSHOT.getEventById = function(id) {
    if (!id || !this.events) return null;
    return this.events.find(e => e.eventID === id) || null;
};

DONKI_SNAPSHOT.getRealEvents = function() {
    return (this.events || []).filter(e => !e.isSimulated);
};

DONKI_SNAPSHOT.getSimulatedEvents = function() {
    return (this.events || []).filter(e => e.isSimulated);
};

DONKI_SNAPSHOT.getRandomEvent = function(includeSimulated = true) {
    const pool = includeSimulated
        ? (this.events || [])
        : this.getRealEvents();
    if (!pool || pool.length === 0) return null;
    const idx = Math.floor(Math.random() * pool.length);
    return pool[idx];
};

